// Category A — a day of bookings laid on a time axis, one column per staff member. A POS draws its
// booking home this way: hour rows
// down a gutter, a header band naming each column, each booking a tinted block whose top and height
// are its start and length, overlapping bookings side by side, and a line at the current time.
//
// Each booking is a React Aria Button that opens it; its accessible name is its title, its description
// and `timeLabel` ("오전 11:00부터 2시간"), because its position on the grid says nothing to a screen
// reader. Each column is a group named by its label, and bookings read in start order within it.
//
// The booking's colour (`swatch`) is the owner's product colour. It tints the block over the surface
// by `time-grid.event.tint`, a light mix that keeps the default ink readable for pastel product
// colours; it is not measured for every colour an owner could pick, so a dark swatch is the caller's to
// avoid until the categorical palette lands.
//
// Bookings outside startHour–endHour are clamped to the grid, and one that ends at or before it
// starts is not drawn. The grid is a ScrollArea, so it takes a tab stop only while it overflows.
//
// Times are minutes from midnight, and every label is the caller's: the grid formats nothing.
//
// ponytail: no drag to move or resize, no tap on an empty slot to create, no week view, no staff
// colour dot in the header; the scope of this unit is open.
// The FAB that creates a booking is the screen's.
import { Button as AriaButton } from "react-aria-components";
import { useCallback, useEffect, useRef } from "react";
import type { CSSProperties, ReactNode, Ref } from "react";
import { ScrollArea } from "./ScrollArea";
import "./TimeGrid.css";

export interface TimeGridColumn {
  /** Stable key, matched by a booking's `columnId`. */
  id: string;
  /** The column's name, e.g. "김 쌤" or "미지정". */
  label: string;
}

export interface TimeGridEvent {
  /** Stable key. */
  id: string;
  /** The column the booking sits in. */
  columnId: string;
  /** Start, in minutes from midnight. */
  start: number;
  /** End, in minutes from midnight. */
  end: number;
  /** The first line, e.g. the customer's name. */
  title: ReactNode;
  /** The second line, e.g. the service. */
  description?: ReactNode;
  /** When it is, for assistive technology, e.g. "오전 11:00부터 2시간". */
  timeLabel: string;
  /** The owner's colour for the booking's product, as a CSS colour. */
  swatch?: string;
}

export interface TimeGridProps {
  /** The columns, in order. */
  columns: TimeGridColumn[];
  /** The bookings, in any order. */
  events: TimeGridEvent[];
  /** The first hour shown, 0 to 23. */
  startHour: number;
  /** The hour the grid ends at, after `startHour`. */
  endHour: number;
  /** An hour's label in the gutter, e.g. `(h) => h < 12 ? \`오전 ${h}\` : \`오후 ${h === 12 ? 12 : h - 12}\``. */
  hourLabel: (hour: number) => string;
  /** The current time in minutes from midnight; omit on a day other than today. */
  now?: number;
  /** The current time as shown on the line's chip, e.g. "2:14". */
  nowLabel?: string;
  /** Called with a booking's id when it is pressed. */
  onEventPress?: (id: string) => void;
  /** Accessible name of the grid, e.g. "9월 27일 예약". */
  "aria-label": string;
  /** Additional class (optional). sd-time-grid is always preserved. */
  className?: string;
  /** Forwarded to the root element. */
  ref?: Ref<HTMLDivElement>;
}

/** Lane and lane count per event: overlapping bookings in a column share its width. */
function lanes(events: TimeGridEvent[]) {
  const out = new Map<string, { lane: number; lanes: number }>();
  let cluster: TimeGridEvent[] = [];
  let ends: number[] = [];
  let clusterEnd = -1;
  const flush = () => {
    for (const e of cluster) out.set(e.id, { lane: out.get(e.id)!.lane, lanes: ends.length });
    cluster = [];
    ends = [];
  };
  for (const e of [...events].sort((a, b) => a.start - b.start || b.end - a.end)) {
    if (e.start >= clusterEnd) flush();
    let lane = ends.findIndex((end) => end <= e.start);
    if (lane < 0) lane = ends.push(e.end) - 1;
    else ends[lane] = e.end;
    out.set(e.id, { lane, lanes: 0 });
    cluster.push(e);
    clusterEnd = Math.max(clusterEnd, e.end);
  }
  flush();
  return out;
}

/**
 * Writes a description's whole-line count, which its line clamp reads to end the last kept line in an
 * ellipsis. It is the count the stylesheet's height already rounds to: the slot plus the booking's
 * bottom inset, over one line. Written as a custom property, so it never re-renders.
 */
function measureDescription(slot: Element) {
  const text = slot.firstElementChild as HTMLElement | null;
  const event = slot.parentElement;
  if (!text || !event) return;
  const lh = parseFloat(getComputedStyle(text).lineHeight);
  const pad = parseFloat(getComputedStyle(event).paddingBlockEnd) || 0;
  if (!(lh > 0)) return text.style.removeProperty("--sd-time-grid-description-lines");
  // A count of 0 leaves the clamp invalid, and the rounded height alone hides the text.
  text.style.setProperty("--sd-time-grid-description-lines", String(Math.floor((slot.clientHeight + pad) / lh + 0.01)));
}

export function TimeGrid({
  columns,
  events,
  startHour,
  endHour,
  hourLabel,
  now,
  nowLabel,
  onEventPress,
  "aria-label": ariaLabel,
  className,
  ref,
}: TimeGridProps) {
  const first = startHour * 60;
  const last = endHour * 60;
  const visible = events
    .filter((e) => e.end > e.start && e.end > first && e.start < last)
    .map((e) => ({ ...e, start: Math.max(e.start, first), end: Math.min(e.end, last) }));
  const hours = Array.from({ length: endHour - startHour }, (_, i) => startHour + i);
  const origin = startHour * 60;
  const showNow = now !== undefined && now >= origin && now <= endHour * 60;
  // Measured whenever a slot or its text resizes: a viewport rung that moves the hour height moves
  // the slot, and a brand that moves the line height moves the text. One observer for the grid, and
  // a stable ref callback, so a re-render with a new `events` array observes nothing again.
  const observer = useRef<ResizeObserver | null>(null);
  const observeDescription = useCallback((slot: HTMLSpanElement | null) => {
    const text = slot?.firstElementChild;
    if (!slot || !text || typeof ResizeObserver === "undefined") return;
    const ro = (observer.current ??= new ResizeObserver((entries) =>
      entries.forEach((e) => {
        const owner = e.target.closest(".sd-time-grid__event-description");
        if (owner) measureDescription(owner);
      }),
    ));
    ro.observe(slot);
    ro.observe(text);
    return () => {
      ro.unobserve(slot);
      ro.unobserve(text);
    };
  }, []);
  // The observer goes with the grid. A remount (StrictMode's included) builds a fresh one.
  useEffect(
    () => () => {
      observer.current?.disconnect();
      observer.current = null;
    },
    [],
  );
  const vars = { "--sd-time-grid-columns": columns.length, "--sd-time-grid-hours": hours.length } as CSSProperties;
  return (
    <ScrollArea
      ref={ref}
      orientation="both"
      role="group"
      aria-label={ariaLabel}
      className={className ? `sd-time-grid ${className}` : "sd-time-grid"}
      style={vars}
    >
      <div className="sd-time-grid__header" aria-hidden="true">
        <span className="sd-time-grid__corner" />
        {columns.map((c) => (
          <span key={c.id} className="sd-time-grid__column-label sd-type-label-medium">
            {c.label}
          </span>
        ))}
      </div>
      <div className="sd-time-grid__body" data-now-label={showNow && nowLabel ? true : undefined}>
        <div className="sd-time-grid__gutter" aria-hidden="true" />
        {hours.map((h, i) => (
          <span key={h} className="sd-time-grid__hour sd-type-caption-medium" style={{ gridRow: i + 1 }} aria-hidden="true">
            {hourLabel(h)}
          </span>
        ))}
        {columns.map((c, k) => {
          const mine = visible.filter((e) => e.columnId === c.id).sort((a, b) => a.start - b.start);
          const placed = lanes(mine);
          return (
            <div key={c.id} role="group" aria-label={c.label} className="sd-time-grid__column" style={{ gridColumn: k + 2 }}>
              {mine.map((e) => {
                const { lane, lanes: n } = placed.get(e.id)!;
                const style = {
                  "--sd-time-grid-start": e.start - origin,
                  "--sd-time-grid-length": e.end - e.start,
                  "--sd-time-grid-lane": lane,
                  "--sd-time-grid-lanes": n,
                  ...(e.swatch ? { "--sd-time-grid-swatch": e.swatch } : {}),
                } as CSSProperties;
                return (
                  <AriaButton
                    key={e.id}
                    className="sd-time-grid__event"
                    data-swatch={e.swatch ? true : undefined}
                    style={style}
                    onPress={onEventPress && (() => onEventPress(e.id))}
                  >
                    <span className="sd-time-grid__event-title sd-type-body-medium-emphasized">{e.title}</span>
                    {e.description != null && (
                      <span ref={observeDescription} className="sd-time-grid__event-description">
                        <span className="sd-time-grid__event-description-text sd-type-caption-medium">{e.description}</span>
                      </span>
                    )}
                    <span className="sd-visually-hidden">{e.timeLabel}</span>
                  </AriaButton>
                );
              })}
            </div>
          );
        })}
        {showNow && (
          <div className="sd-time-grid__now" style={{ "--sd-time-grid-start": now - origin } as CSSProperties} aria-hidden="true">
            {nowLabel && <span className="sd-time-grid__now-label sd-type-caption-medium">{nowLabel}</span>}
          </div>
        )}
      </div>
    </ScrollArea>
  );
}

/* The grid scrolls inside the height its parent gives it, and sideways once its columns cannot each
   keep their minimum. The header band and the body share one column template: the gutter, then the
   columns in equal shares of at least `column.min-width`. Bookings and the current-time line are
   placed by minutes the component writes as custom properties. While the columns scroll sideways the
   gutter and the header's corner stay pinned at the inline start, as a scheduler's time column does. */
.sd-time-grid {
  display: flex;
  flex-direction: column;
  min-block-size: 0;
  /* The grid paints its own surface, the one the pinned gutter and each booking's tint are drawn
     from, so it opts out of the scrollport's compensated gutter: the negative margin would grow the
     painted surface past its slot. */
  margin: 0;
  padding: 0;
  background: var(--sd-time-grid-background);
  /* The header band and the gutter stay pinned over what scrolls, so a booking the keyboard brings
     into view stops clear of both instead of under them (WCAG 2.4.11). */
  scroll-padding-block-start: var(--sd-time-grid-header-height);
  scroll-padding-inline-start: var(--sd-time-grid-gutter-width);
  --sd-time-grid-template: var(--sd-time-grid-gutter-width) repeat(var(--sd-time-grid-columns), minmax(var(--sd-time-grid-column-min-width), 1fr));
}

/* Both bands grow to the template's minimum, so the header's band and the body's columns run past the
   scrollport together: `min-content`, where the equal shares sit at their minimum in both alike. */
.sd-time-grid__header,
.sd-time-grid__body {
  min-inline-size: min-content;
}

.sd-time-grid__header {
  position: sticky;
  inset-block-start: 0;
  z-index: 1;
  display: grid;
  grid-template-columns: var(--sd-time-grid-template);
  background: var(--sd-time-grid-header-background);
  color: var(--sd-time-grid-header-foreground);
}

/* The header's cell over the gutter: pinned with it, in the band's fill, so a label scrolling
   sideways passes under it. */
.sd-time-grid__corner {
  position: sticky;
  inset-inline-start: 0;
  background: var(--sd-time-grid-header-background);
}

.sd-time-grid__column-label {
  padding: var(--sd-time-grid-header-padding);
  border-inline-start: var(--sd-time-grid-line-width) solid var(--sd-time-grid-line);
  text-align: center;
  /* One line ending in an ellipsis, as a header label does: never a word split across lines. */
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sd-time-grid__body {
  position: relative;
  display: grid;
  grid-template-columns: var(--sd-time-grid-template);
  grid-template-rows: repeat(var(--sd-time-grid-hours), var(--sd-time-grid-hour-height));
  padding-block: var(--sd-time-grid-body-padding-block);
  /* The z-indexes below order the body's own parts, gutter over bookings and the now line over the
     gutter, so the body is their stacking context and the sticky header still passes over all of it. */
  isolation: isolate;
  /* Every text stands one text inset in (ADR-0053), the now-label pill or not. */
  --sd-time-grid-hour-padding-current: var(--sd-time-grid-text-padding-inline);
}

/* The gutter's surface, pinned at the inline start over the columns that scroll under it. It spans
   the hour rows and the body's block padding, so nothing that scrolls shows past it. */
.sd-time-grid__gutter {
  position: sticky;
  inset-inline-start: 0;
  z-index: 2;
  grid-column: 1;
  grid-row: 1 / -1;
  margin-block: calc(-1 * var(--sd-time-grid-body-padding-block));
  background: var(--sd-time-grid-background);
}

/* An hour's label sits centred on its rule; the rules are the columns' own background. Pinned with
   the gutter, and painted after it. */
.sd-time-grid__hour {
  position: sticky;
  inset-inline-start: 0;
  z-index: 2;
  grid-column: 1;
  align-self: start;
  color: var(--sd-time-grid-hour-foreground);
  translate: 0 -50%;
  padding-inline-start: var(--sd-time-grid-hour-padding-current);
}

.sd-time-grid__column {
  position: relative;
  grid-row: 1 / -1;
  border-inline-start: var(--sd-time-grid-line-width) solid var(--sd-time-grid-line);
  background: repeating-linear-gradient(
    to bottom,
    var(--sd-time-grid-line) 0 var(--sd-time-grid-line-width),
    transparent var(--sd-time-grid-line-width) var(--sd-time-grid-hour-height)
  );
}

.sd-time-grid__event {
  position: absolute;
  isolation: isolate;
  inset-block-start: calc(var(--sd-time-grid-start) * var(--sd-time-grid-hour-height) / 60);
  block-size: calc(var(--sd-time-grid-length) * var(--sd-time-grid-hour-height) / 60 - var(--sd-time-grid-event-gap));
  inset-inline-start: calc(100% * var(--sd-time-grid-lane) / var(--sd-time-grid-lanes) + var(--sd-time-grid-event-gap));
  inline-size: calc(100% / var(--sd-time-grid-lanes) - 2 * var(--sd-time-grid-event-gap));
  display: flex;
  flex-direction: column;
  align-items: stretch;
  margin: 0;
  padding: var(--sd-time-grid-event-padding);
  border: 0;
  border-radius: var(--sd-time-grid-event-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
  background: var(--sd-time-grid-event-background);
  color: var(--sd-time-grid-event-foreground);
  text-align: start;
  overflow: hidden;
  cursor: pointer;
  outline: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-time-grid-event-state-hover-current: var(--sd-state-hover-neutral-subtle);
  --sd-time-grid-event-state-pressed-current: var(--sd-state-pressed-neutral-subtle);
}
/* Overlapping bookings share a column, so a lane can be narrower than a word. A line that does not
   fit ends in an ellipsis rather than clipping mid-glyph at the lane's edge. The title keeps one
   line, as a scheduler's event does; `overflow: hidden` drops a flex item's min size to 0, so it
   refuses to shrink and the booking clips it only when too short for even that. */
.sd-time-grid__event-title {
  flex-shrink: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* The description wraps by word into what the title leaves, in whole lines only, and when it drops
   lines the last one it keeps ends in an ellipsis. The slot takes the rest of the booking, and the
   text is that height plus the bottom inset rounded down to its own line, so a booking too short for
   a line shows none instead of half of one. The clamp that draws the ellipsis needs that count as an
   integer, which CSS cannot divide out of a length, so the component measures it and writes it;
   until it has, the height alone holds the whole lines. A word longer than the lane breaks rather
   than running past its edge. */
.sd-time-grid__event-description {
  flex: 1 1 0;
  min-block-size: 0;
}
.sd-time-grid__event-description-text {
  /* No clamp until the component writes the count over this, inline. */
  --sd-time-grid-description-lines: none;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--sd-time-grid-description-lines);
  max-block-size: round(down, calc(100% + var(--sd-time-grid-event-padding)), 1lh);
  overflow: hidden;
  overflow-wrap: anywhere;
}

.sd-time-grid__event[data-swatch] {
  background: color-mix(
    in srgb,
    var(--sd-time-grid-swatch) calc(var(--sd-time-grid-event-tint) * 100%),
    var(--sd-time-grid-event-tint-base)
  );
}
.sd-time-grid__event::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-time-grid__event[data-hovered]::after {
  background: var(--sd-time-grid-event-state-hover-current);
}
.sd-time-grid__event[data-pressed]::after {
  background: var(--sd-time-grid-event-state-pressed-current);
}
.sd-time-grid__event[data-focus-visible] {
  z-index: 1;
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}

/* Over the gutter, so the line and its label read across it. */
.sd-time-grid__now {
  position: absolute;
  z-index: 2;
  inset-inline: 0;
  inset-block-start: calc(var(--sd-time-grid-body-padding-block) + var(--sd-time-grid-start) * var(--sd-time-grid-hour-height) / 60);
  border-block-start: var(--sd-time-grid-now-width) solid var(--sd-time-grid-now-line);
  pointer-events: none;
}

/* Pinned at the inline start with the gutter it sits in. */
.sd-time-grid__now-label {
  position: sticky;
  inset-inline-start: 0;
  display: block;
  inline-size: fit-content;
  translate: 0 -50%;
  padding-inline: var(--sd-time-grid-now-padding);
  border-radius: var(--sd-time-grid-now-radius);
  corner-shape: round;
  background: var(--sd-time-grid-now-background);
  color: var(--sd-time-grid-now-foreground);
  font-variant-numeric: tabular-nums;
}
